shaderSourceByName.blacklight:
uniform sampler2D uTexture;
uniform float uTime;
uniform vec2 uResolution;
varying vec2 vUv;

void main() {
  vec4 tex = texture2D(uTexture, vUv);

  // Extract luminance
  float luma = dot(tex.rgb, vec3(0.299, 0.587, 0.114));

  // Blacklight color palette - purple/blue glow
  vec3 uvColor = vec3(0.4, 0.1, 0.8);
  vec3 glowColor = vec3(0.8, 0.3, 1.0);

  // Bright areas get the glow, dark areas stay dark
  float glow = smoothstep(0.3, 0.7, luma);

  // Mix between deep purple and bright glow
  vec3 color = mix(tex.rgb * uvColor * 0.3, tex.rgb * glowColor, glow);

  // Add subtle pulse
  float pulse = sin(uTime * 2.0) * 0.05 + 1.0;
  color *= pulse;

  color.g *= 0.1;
  color.r *= 0.25;
  color.b *= 1.2;

  // Boost contrast
  color = pow(color+0.02, vec3(1.8)) * mix(2.0, 0.2, smoothstep(0.0, 0.8, length(vUv-0.5)));


  float lumaV = dot(tex.rgb, vec3(0.299, 0.587, 0.114));
  float edgesV = fwidth(lumaV) * 10.0;
  vec3 edges = vec3(pow(edgesV, 1.2));

  color += edges * 0.5 * vec3(0.0, 0.2, 1.0);
  color *= vec3(1.0) + edges * 1.5;

  gl_FragColor = vec4(color, 1.0);
}

shaderSourceByName.hero:
uniform sampler2D uTexture;
uniform float uTime;
uniform vec2 uResolution;
uniform float uScanActive;
varying vec2 vUv;

void main() {
  vec2 uv = vUv;

  // Sample texture at full resolution
  vec4 texColor = texture2D(uTexture, uv);

  // Pixelate to grid
  vec2 pixelSize = 20.0 / uResolution;
  vec2 gridUv = floor(uv / pixelSize) * pixelSize;

  // Sample texture and compute luminance
  vec4 gridColor = texture2D(uTexture, gridUv);
  float luma = dot(gridColor.rgb, vec3(0.299, 0.587, 0.114));

  // 4x4 Bayer dither matrix
  mat4 bayer = mat4(
    0.0, 8.0, 2.0, 10.0,
    12.0, 4.0, 14.0, 6.0,
    3.0, 11.0, 1.0, 9.0,
    15.0, 7.0, 13.0, 5.0
  );

  // Get position in dither pattern
  vec2 pc = mod(floor(uv * uResolution), 4.0);
  float threshold = bayer[int(pc.x)][int(pc.y)] / 25.0;

  // Apply dither
  float dither = step(threshold, luma);

  // Dark output with slight gamma curve
  vec3 color = pow(vec3(dither-0.1), vec3(5.0));

  gl_FragColor = vec4(color * pow(texColor.rgb, vec3(1.5)), 1.0);
}

