shaderSourceByName.marketing:
uniform sampler2D uTexture;
uniform sampler2D uMudNormal;
uniform float uTime;
uniform vec2 uResolution;
varying vec2 vUv;

const float PI = 3.1415926535897932;

// Speed settings
const float speed = 0.04;
const float speed_x = 0.06;
const float speed_y = 0.06;

// Refraction settings
const float emboss = 0.80;
const float intensity = 1.5;
const int steps = 8;
const float frequency = 8.0;
const int angle = 7;

// Reflection settings
const float delta = 60.0;
const float gain = 700.0;
const float reflectionCutOff = 0.012;
const float reflectionIntensity = 200000.0;

float col(vec2 coord, float time) {
  float delta_theta = 2.0 * PI / float(angle);
  float c = 0.0;
  float theta = 0.0;
  for (int i = 0; i < steps; i++) {
    vec2 adjc = coord;
    theta = delta_theta * float(i);
    adjc.x += cos(theta) * time * speed + time * speed_x;
    adjc.y -= sin(theta) * time * speed - time * speed_y;
    c = c + cos((adjc.x * cos(theta) - adjc.y * sin(theta)) * frequency) * intensity;
  }
  return cos(c);
}

void main() {
  float time = uTime * 1.3;

  // Apply mud texture distortion to base UV
  vec3 mud = texture2D(uMudNormal, vUv * 2.0 + time * 0.02).rgb;
  vec2 mudOffset = (mud.rg - 0.5) * 0.08;

  vec2 p = vUv + mudOffset;
  vec2 c1 = p;
  vec2 c2 = p;

  float cc1 = col(c1, time);

  c2.x += 1.0 / delta;
  float dx = emboss * (cc1 - col(c2, time)) / delta;

  c2.x = p.x;
  c2.y += 1.0 / delta;
  float dy = emboss * (cc1 - col(c2, time)) / delta;

  c1.x += dx * 2.0;
  c1.y = 1.0 - (c1.y + dy * 2.0);

  float alpha = 1.0 + dot(dx, dy) * gain;

  float ddx = dx - reflectionCutOff;
  float ddy = dy - reflectionCutOff;
  if (ddx > 0.0 && ddy > 0.0) {
    alpha = pow(alpha, ddx * ddy * reflectionIntensity);
  }

  vec4 texColor = texture2D(uTexture, c1) * alpha;

  texColor.rgb = pow(texColor.rgb, vec3(1.8));
  gl_FragColor = texColor;
}

