  // Sample texture and compute luminance
  vec4 gridColor = texture2D(uTexture, gridUv);
  float luma = dot(gridColor.rgb, vec3(0.299, 0.587, 0.114));

  // 4x4 Bayer dither matrix
  mat4 bayer = mat4(
    0.0, 8.0, 2.0, 10.0,
    12.0, 4.0, 14.0, 6.0,
