graffiti.fragmentShader:
uniform sampler2D uTexture;
uniform sampler2D uMudNormal;
uniform float uTime;
uniform float uVisibility;
uniform float uTransition;
uniform float uScrollOffset;
uniform float uPlaneAspect;
varying vec2 vUv;

float hash(float n) {
  return fract(sin(n) * 43758.5453);
}

void main() {
  // Scale UVs for 1:2 texture aspect ratio and plane aspect ratio
  // Texture is 1:2 (aspect 0.5), adjust X based on plane aspect
  float textureAspect = 1.0;
  vec2 scaledUv = vec2(vUv.x, vUv.y * 0.25 * (textureAspect / uPlaneAspect));

  // Scroll UVs vertically based on scroll position (wraps due to RepeatWrapping)
  // Flip X for correct orientation
  vec2 scrolledUv = vec2(scaledUv.x, (1.0-scaledUv.y) + uScrollOffset * 1.5 - 0.05);

  // Sample mud normal for UV distortion
  vec2 mudUv = vUv * 1.5 + uTime * 0.01;
  vec3 mudNormal = texture2D(uMudNormal, mudUv).rgb * 2.0 - 1.0;

  // Distort UVs based on transition amount
  float distortAmount = uTransition * 0.05;
  vec2 distortedUv = scrolledUv + mudNormal.xy * distortAmount;

  vec4 texColor = texture2D(uTexture, distortedUv);
  texColor.rgb = pow(texColor.rgb * 1.2, vec3(1.5));

  // Flicker during transitions
  float flickerStrength = uTransition * 0.5;
  float noise1 = hash(floor(uTime * 15.0) + vUv.x * 10.0);
  float noise2 = hash(floor(uTime * 23.0) + vUv.y * 7.0);
  float noise3 = hash(floor(uTime * 31.0));
  float flicker = 1.0 - flickerStrength * (noise1 * 0.4 + noise2 * 0.3 + noise3 * 0.3);

  float alpha = uVisibility * flicker;

  vec3 color = texColor.rgb * alpha;
  color *= 2.0 + sin(uTime * 3.0 + vUv.y * 6.0) * 0.25;

  gl_FragColor = vec4(color, 1.0);
}

