boids.fragmentShader:
precision highp float;
uniform vec3 uColor;
varying vec2 vUv;

void main() {
  float t = vUv.y;
  float endFade = smoothstep(0.0, 0.15, t) * smoothstep(1.0, 0.8, t);
  float edgeFade = 1.0 - abs(vUv.x - 0.5) * 2.0;
  edgeFade = smoothstep(0.0, 0.4, edgeFade);

  vec3 col = uColor * 1.8;
  float alpha = endFade * edgeFade * 0.7;
  gl_FragColor = vec4(col, alpha);
}

discardShader.fragment:
float noiseValue = fbm3d(vWorldPosition * 0.15);
noiseValue = smoothstep(-0.5, 0.5, noiseValue);

float threshold = 1.0 - uVisibility;
if (noiseValue < threshold) {
  discard;
}

float edgeWidth = 0.02;
float edge = smoothstep(threshold, threshold + edgeWidth, noiseValue);
gl_FragColor.rgb = mix(gl_FragColor.rgb * 10.0, gl_FragColor.rgb, edge);
